<div class="judul-baris"><h1><?= e($res['label']) ?></h1><a class="btn" href="index.php?r=<?= e($key) ?>&amp;a=create">+ Tambah</a></div>
<form method="get" class="cari"><input type="hidden" name="r" value="<?= e($key) ?>"><input name="q" type="search" value="<?= e($q) ?>" placeholder="Cari data..."><button>Cari</button><?php foreach ($res['filters'] ?? [] as $col): ?><label><?= e(ucfirst($col)) ?><select name="<?= e($col) ?>"><option value="">Semua</option><?php $rule=$res['fields'][$col] ?? []; $opts=$rule['type']==='fk' ? ($fk[$col]??[]) : array_combine($rule['options']??[], $rule['options']??[]); foreach ($opts as $val=>$label): ?><option value="<?= e((string)$val) ?>"<?= (string)($filters[$col]??'')===(string)$val?' selected':'' ?>><?= e((string)$label) ?></option><?php endforeach; ?></select></label><?php endforeach; ?><button>Filter</button></form><p class="info"><?= $result['total'] ?> data</p>
<div class="tabel-wrap"><table><thead><tr><?php foreach ($res['list'] as $col): ?><th><?= e($res['fields'][$col]['label']??$col) ?></th><?php endforeach; ?><th>Aksi</th></tr></thead><tbody><?php foreach ($result['rows'] as $item): ?><tr><?php foreach ($res['list'] as $col): ?><td><?= e(display_value($res['fields'][$col]??['type'=>'text'], $item[$col]??null, $fk[$col]??[])) ?></td><?php endforeach; ?><td class="aksi"><?php foreach ($res['links']??[] as $label=>$link): ?><a href="index.php?r=<?= e(str_replace('{id}',(string)$item['id'],$link)) ?>"><?= e($label) ?></a><?php endforeach; ?><a href="index.php?r=<?= e($key) ?>&amp;a=edit&amp;id=<?= (int)$item['id'] ?>">Edit</a><form method="post" action="index.php?r=<?= e($key) ?>&amp;a=delete&amp;id=<?= (int)$item['id'] ?>" onsubmit="return confirm('Hapus data ini?')"><?= csrf_field() ?><button class="hapus">Hapus</button></form></td></tr><?php endforeach; ?><?php if (!$result['rows']): ?><tr><td colspan="<?= count($res['list'])+1 ?>">Belum ada data.</td></tr><?php endif; ?></tbody></table></div>
<?php if ($result['pages']>1): ?><nav class="paginasi"><?php for ($p=1;$p<=$result['pages'];$p++): $url='index.php?'.http_build_query(['r'=>$key,'p'=>$p,'q'=>$q]+$filters); ?><a class="<?= $p===$result['page']?'aktif':'' ?>" href="<?= e($url) ?>"><?= $p ?></a><?php endfor; ?></nav><?php endif; ?>
